244	     * exceeds 365 days, measured from {@code registrationDate} to the current date. Not persisted.
245	     */
246	    @Transient
247	    public Integer getMembershipPoints() {
248	        int points = 0;
249	        if (this.email != null && !this.email.isBlank()) {
250	            points += 2;
251	        }
252	        if (this.namesakeCount != null && this.namesakeCount == 0) {
253	            points += 1;
254	        }
255	        if (this.householdSize != null && this.householdSize >= 3) {
256	            points += 2;
257	        }
258	        if (this.registrationDate != null
259	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
260	            points += 3;
261	        }
262	        return points;
263	    }
