293	    /**
294	     * A single Luhn check digit (0 to 9) computed over the digits contained in the
295	     * {@code customerCode}. Non-digit characters are ignored. Not persisted.
296	     */
297	    @Transient
298	    public Integer getCheckDigit() {
299	        String code = this.customerCode == null ? "" : this.customerCode;
300	        int sum = 0;
301	        boolean dbl = true;
302	        for (int i = code.length() - 1; i >= 0; i--) {
303	            char c = code.charAt(i);
304	            if (c < '0' || c > '9') {
305	                continue;
306	            }
307	            int d = c - '0';
